import{at as e,it as t,n,vt as r}from"./chunks/framework.BZu6EPoN.js";var i=JSON.parse(`{"title":"可得容量计算方法","description":"","frontmatter":{"title":"可得容量计算方法","date":"2025-09-09","summary":"存储设备可存入的用户数据总量。","tags":["硬件"],"draft":false,"authors":["default"]},"headers":[],"relativePath":"zh/blog/method-for-available-capacity.md","filePath":"zh/blog/method-for-available-capacity.md"}`),a={name:`zh/blog/method-for-available-capacity.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="硬盘可得容量计算方法" tabindex="-1">硬盘可得容量计算方法 <a class="header-anchor" href="#硬盘可得容量计算方法" aria-label="Permalink to “硬盘可得容量计算方法”">​</a></h1><p>在购买或使用硬盘（HDD、SSD、移动硬盘、U 盘等）时，很多用户会发现：<strong>实际可用容量往往比硬盘厂商标注的容量要小</strong>。这并不是硬盘“偷工减料”，而是因为计算方法和文件系统的差异。本文将带你了解硬盘可得容量的计算方法，以及为什么会出现“容量缩水”的现象。</p><p>utf8mb4 和utf8的区别</p><h6 id="chatgpt-说" tabindex="-1">ChatGPT 说： <a class="header-anchor" href="#chatgpt-说" aria-label="Permalink to “ChatGPT 说：”">​</a></h6><p>好问题 👍，这其实是 MySQL 的一个“坑点”。</p><hr><h2 id="_1-utf8-和-utf8mb4-在-mysql-里的区别" tabindex="-1">1. <strong>utf8 和 utf8mb4 在 MySQL 里的区别</strong> <a class="header-anchor" href="#_1-utf8-和-utf8mb4-在-mysql-里的区别" aria-label="Permalink to “1. utf8 和 utf8mb4 在 MySQL 里的区别”">​</a></h2><h3 id="✅-mysql-里的-utf8" tabindex="-1">✅ MySQL 里的 <code>utf8</code> <a class="header-anchor" href="#✅-mysql-里的-utf8" aria-label="Permalink to “✅ MySQL 里的 utf8”">​</a></h3><ul><li><strong>不是标准的 UTF-8</strong>！</li><li>只能存储 <strong>1–3 字节</strong>的 UTF-8 字符（最多支持 Unicode U+FFFF，BMP 平面）。</li><li>存不了 <strong>4 字节字符</strong>（比如 emoji、某些特殊汉字、少数民族文字、古文字）。</li><li>举例： <ul><li><code>&quot;张&quot;</code> ✅ 可以存</li><li><code>&quot;😀&quot;</code> ❌ 存不下，会报错：<code>Incorrect string value</code></li></ul></li></ul><hr><h3 id="✅-mysql-里的-utf8mb4" tabindex="-1">✅ MySQL 里的 <code>utf8mb4</code> <a class="header-anchor" href="#✅-mysql-里的-utf8mb4" aria-label="Permalink to “✅ MySQL 里的 utf8mb4”">​</a></h3><ul><li>才是 <strong>真正完整的 UTF-8 实现</strong>（支持 1–4 字节）。</li><li>能存所有 Unicode 字符，包括 emoji。</li><li>从 MySQL 5.5.3 开始支持。</li><li>建议在新项目里 <strong>统一用 utf8mb4</strong>，避免以后存不下 emoji 或其他字符。</li></ul><hr><h2 id="_2-存储对比" tabindex="-1">2. <strong>存储对比</strong> <a class="header-anchor" href="#_2-存储对比" aria-label="Permalink to “2. 存储对比”">​</a></h2><table tabindex="0"><thead><tr><th>字符集</th><th>每字符最大字节</th><th>能否存 emoji</th><th>备注</th></tr></thead><tbody><tr><td>utf8</td><td>3 字节</td><td>❌ 不行</td><td>MySQL 特有的“阉割版 UTF-8”</td></tr><tr><td>utf8mb4</td><td>4 字节</td><td>✅ 可以</td><td>真正的 UTF-8</td></tr></tbody></table><hr><h2 id="_3-性能差异" tabindex="-1">3. <strong>性能差异</strong> <a class="header-anchor" href="#_3-性能差异" aria-label="Permalink to “3. 性能差异”">​</a></h2><ul><li>utf8mb4 比 utf8 多 1 个字节存储开销，但差异很小。</li><li>绝大多数场景（尤其 Web、移动端）推荐用 utf8mb4。</li></ul><hr><h2 id="_4-最佳实践" tabindex="-1">4. <strong>最佳实践</strong> <a class="header-anchor" href="#_4-最佳实践" aria-label="Permalink to “4. 最佳实践”">​</a></h2><ol><li><p><strong>库、表、列</strong> 全部用 utf8mb4</p><div class="language-" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>CREATE DATABASE mydb DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;</span></span></code></pre></div></li><li><p><strong>连接编码</strong>也要设置 utf8mb4（否则插入 emoji 还是会报错）：</p><div class="language-" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>SET NAMES utf8mb4;</span></span></code></pre></div></li><li><p>如果历史数据库用 utf8，可以用：</p><div class="language-" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ALTER TABLE mytable CONVERT TO CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;</span></span></code></pre></div></li></ol><hr><p>👉 总结：</p><ul><li><code>utf8</code> = 残缺的 UTF-8，只支持 3 字节</li><li><code>utf8mb4</code> = 真正的 UTF-8，支持 4 字节，推荐永远用它</li></ul>`,24)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};